public OCFile getFileByPath(String path) {
  Cursor c = getFileCursorForValue(ProviderTableMeta.FILE_PATH, path);
  OCFile file = null;
  try {
    if (c.moveToFirst()) {
      try {
        file = createFileInstance(c);
      } catch (SecurityException e) {
        // 处理文件实例创建时的安全异常
        Log.e("FileException", "Security exception when creating file instance", e);
      }
    }
  } finally {
    c.close();
  }

  if (file == null && OCFile.ROOT_PATH.equals(path)) {
    try {
      return createRootDir();
    } catch (NumberFormatException e) {
      // 处理根目录创建时的数字格式异常
      Log.e("FileException", "Number format exception when creating root dir", e);
      return null;
    }
  }
  return file;
}
